#!/usr/bin/env node
// run_experiment.mjs — Full pipeline of an experiment: generate (agent) → acceptance gate (PostgreSQL from the app's
// docker-compose.yml) → [R2: additional requirements (agent)] → evaluate maintainability → comparison. Port of run_experiment.py
// (see it for the phases, the outputs and the security note: it runs code generated by an LLM).
//   node js/run_experiment.mjs --agent claude --level N2 --model claude-sonnet-5-5
//   node js/run_experiment.mjs --agent claude --level N1 --domain cinema --phase initial,r2 --model …
//   node js/run_experiment.mjs --agent claude --level N1 --existing-app ./my_app --skip-acceptance --model …
import { spawnSync } from "node:child_process";
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { dumps, get, loadJson, readText, str } from "./lib/py.mjs";
import { HERE, modelMissing, nowIso } from "./evaluator/common.mjs";
import { MODEL_ERROR } from "./evaluate.mjs";
import * as rt from "./pg_runtime.mjs";
import * as tu from "./token_usage.mjs";

const SPECS = path.join(HERE, "specs");
const AGENTS = { claude: ["claude", "-p", "--output-format", "json", "--dangerously-skip-permissions"], codex: ["codex", "exec", "--json", "--full-auto", "-"] };
const PROMPT_ARG = "{prompt}", PHASES = ["initial", "r2"], R2_SPEC = "r2-additional-requirements.md";
const ACCEPTANCE_FILE = "acceptance.json", CONFORMANCE_FILE = "contract_conformance.json";
const WIN = process.platform === "win32";
const NODE = process.execPath, JS = path.join(HERE, "js");
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

function which(name) {
  const exts = WIN ? ["", ...(process.env.PATHEXT || ".EXE").split(";")] : [""];
  for (const d of (process.env.PATH || "").split(path.delimiter)) for (const e of exts) { const p = path.join(d, name + e); try { if (fs.statSync(p).isFile()) return p; } catch { /* next */ } }
  return null;
}

/** Return code of `cmd` (its output to `logFd`, or to this process's stdout); 124 on a timeout, 127 when the program is missing. */
function sh(cmd, { cwd, timeout, env, logFd = null, stdinText = null } = {}) {
  const exe = which(cmd[0]) || cmd[0];
  const shell = WIN && /\.(cmd|bat)$/i.test(exe);  // claude.cmd / codex.cmd: a .cmd shim only runs through the shell
  const p = spawnSync(shell ? `"${exe}"` : exe, cmd.slice(1).map((a) => (shell ? `"${a.replaceAll('"', '\\"')}"` : a)), { cwd, env, timeout: timeout ? timeout * 1000 : undefined,
    input: stdinText ?? undefined, stdio: [stdinText !== null ? "pipe" : "ignore", logFd ?? "inherit", logFd ?? "inherit"], shell, windowsHide: true });
  if (p.error && p.error.code === "ETIMEDOUT") return 124;
  if (p.error && p.error.code === "ENOENT") return 127;
  return p.status ?? 1;
}

/** [argv, stdin text]: the prompt goes in the arguments only when the template has {prompt}, otherwise on standard input. */
export function agentCommand(agent, a, prompt) {
  const tpl = a.agent_cmd ? (a.agent_cmd.match(/"[^"]*"|'[^']*'|\S+/g) || []).map((x) => x.replace(/^(["'])(.*)\1$/, "$2")) : AGENTS[agent];
  let cmd, stdinText;
  if (tpl.some((x) => x.includes(PROMPT_ARG))) [cmd, stdinText] = [tpl.map((x) => x.replaceAll(PROMPT_ARG, prompt)), null];
  else [cmd, stdinText] = [[...tpl], prompt];
  if (a.model && !a.agent_cmd) cmd.push("--model", a.model);
  return [cmd, stdinText];
}

export const buildPrompt = (level, domain = "ecommerce") => readText(path.join(SPECS, "combiner-prompt.md")).replaceAll("{LEVEL}", level.toLowerCase()).replaceAll("{DOMAIN}", domain);
export const buildR2Prompt = () => readText(path.join(SPECS, "r2-prompt.md"));

/** Copies the inputs of the phase into the project and returns the prompt (also saved there, as in the manual procedure). */
export function preparePhase(phase, level, domain, project) {
  let prompt;
  if (phase === "initial") {
    fs.mkdirSync(project, { recursive: true });
    for (const f of [`technical-${level.toLowerCase()}.md`, `requirements-${domain}.md`]) fs.copyFileSync(path.join(SPECS, f), path.join(project, f));
    prompt = buildPrompt(level, domain);
    fs.writeFileSync(path.join(project, "PROMPT.md"), prompt, "utf8");
  } else {
    if (!fs.existsSync(path.join(project, "backend"))) throw new Error(`Phase r2 needs the project of phase initial and ${path.join(project, "backend")} does not exist ` +
      "(run --phase initial first, or pass --existing-app).");
    fs.copyFileSync(path.join(SPECS, R2_SPEC), path.join(project, R2_SPEC));
    prompt = buildR2Prompt();
    fs.writeFileSync(path.join(project, "PROMPT-R2.md"), prompt, "utf8");
  }
  return prompt;
}

function generate(agent, level, a, expdir, project, phase = "initial") {
  const prompt = preparePhase(phase, level, a.domain, project);
  const [cmd, stdinText] = agentCommand(agent, a, prompt);
  const exe = which(cmd[0]);
  const ver = exe ? (spawnSync(exe, ["--version"], { encoding: "utf8", shell: WIN && /\.(cmd|bat)$/i.test(exe) }).stdout || "").trim() : "n/a";
  const logName = phase === "initial" ? "agent.log" : `agent-${phase}.log`;
  const t0 = Date.now();
  const fd = fs.openSync(path.join(expdir, logName), "w");
  let rc;
  try { rc = sh(cmd, { cwd: project, timeout: a.agent_timeout, logFd: fd, stdinText }); } finally { fs.closeSync(fd); }
  if (rc === 127) console.log(`  ERROR: '${cmd[0]}' was not found on PATH. Install the agent's CLI or pass --agent-cmd with the full path.`);
  return { agent_cmd: cmd[0], agent_version: ver, rc, seconds: Math.round((Date.now() - t0) / 1000), log: logName };
}

/** Records the tokens of the phase from the agent's output; the phase totals, or null when the output has no usage. */
function recordTokens(runId, phase, logFile, usageDir) {
  let session;
  try { session = tu.parseFile(logFile); } catch { return null; }
  const data = tu.recordPhase(tu.usagePath(runId, usageDir), runId, phase, [session], `run_experiment (${path.basename(logFile)})`);
  return data.phases[phase].totals;
}

async function runBackendGate(be, env, port, expdir, wait = 90, domain = "ecommerce") {
  const fd = fs.openSync(path.join(expdir, "backend.log"), "w");
  try {
    if (sh(rt.npmCmd("install", "--no-audit", "--no-fund"), { cwd: be, timeout: 900, logFd: fd }) !== 0) return { error: "npm install failed (see backend.log)" };
    const proc = rt.startProcess(rt.npmCmd("start"), be, env, fd);
    try {
      if (!(await rt.waitForPort(port, wait))) return { error: `the backend did not open the port within ${wait} s (see backend.log)` };
      await sleep(2000);  // margin for the schema creation and the initial data
      sh([NODE, path.join(JS, "acceptance_check.mjs"), "--base", `http://127.0.0.1:${port}`, "--domain", domain, "--out", path.join(expdir, ACCEPTANCE_FILE), "--app", path.dirname(be)], { logFd: fd });
    } finally { rt.killTree(proc); }
  } finally { fs.closeSync(fd); }
  const f = path.join(expdir, ACCEPTANCE_FILE);
  return fs.existsSync(f) ? loadJson(fs.readFileSync(f, "utf8")) : { error: "acceptance_check produced no result (see backend.log)" };
}

/** Functional gate against PostgreSQL started from the app's own docker-compose.yml. The acceptance result, {skipped, reason}
 *  without Docker, or {error}. Containers and volumes (and the disposable database) are always removed at the end. */
export async function acceptance(project, expdir, runId, wait = 90, domain = "ecommerce") {
  const be = path.join(project, "backend");
  if (!fs.existsSync(be)) return { error: "backend/ does not exist" };
  const composeFile = rt.findCompose(project);
  if (composeFile === null) return { error: "docker-compose.yml not found at the project root (it is a delivery condition of the specification)" };
  const [cmd, why] = rt.dockerStatus();
  if (cmd === null) return { skipped: true, reason: why };
  for (const f of [ACCEPTANCE_FILE, CONFORMANCE_FILE]) fs.rmSync(path.join(expdir, f), { force: true });
  const name = rt.evalDbName(runId);
  const compose = new rt.Compose(cmd, composeFile, name, path.join(expdir, "compose.log"));
  fs.writeFileSync(path.join(expdir, "compose.log"), "", "utf8");
  try {
    const cfg = compose.config();
    const svc = rt.pickPostgresService(cfg);
    if (!svc) return { error: "no PostgreSQL service found in docker-compose.yml (image postgres or POSTGRES_* variables)" };
    const [user, password] = rt.pgCredentials(cfg.services[svc]);
    const [rc, , err] = compose.up(svc);
    if (rc !== 0) return { error: "docker compose up failed (see compose.log): " + rt.mask(err, "").slice(-200) };
    const port = compose.port(svc);
    if (!port) return { error: `service ${svc} does not publish port 5432 to the host, so the gate cannot connect to it` };
    if (!(await compose.waitReady(svc, user)) || !(await rt.waitForPort(port, 30))) return { error: "PostgreSQL did not become ready in time (see compose.log)" };
    if (compose.createDatabase(svc, user, name)[0] !== 0) return { error: `could not create the disposable database ${name} (see compose.log)` };
    const backendPort = rt.freePort();
    const env = Object.fromEntries(Object.entries(process.env).filter(([k]) => k !== "PG_ADMIN_URL" && k !== "NODE_TEST_CONTEXT"));
    Object.assign(env, { PORT: String(backendPort), DATABASE_URL: rt.buildUrl(user, password, "127.0.0.1", port, name) });
    Object.assign(env, rt.backendSecrets(be, env));
    const result = await runBackendGate(be, env, backendPort, expdir, wait, domain);
    const log = path.join(expdir, "backend.log");
    if (fs.existsSync(log)) fs.writeFileSync(log, rt.mask(readText(log), env.DATABASE_URL), "utf8");
    return result;
  } catch (e) { return { error: String(e.message) }; } finally { compose.down(); }
}

async function runPhases(phases, agent, level, a, expdir, project, meta, usageKey, afterPhase = null) {
  const mf = path.join(expdir, "meta.json");
  if (fs.existsSync(mf)) {  // e.g. initial and its gate, when only r2 runs now
    const old = loadJson(fs.readFileSync(mf, "utf8"));
    for (const [k, v] of Object.entries(old)) if (k.startsWith("generation") || k === "acceptance") meta[k] = v;
  }
  for (const phase of phases) {
    const key = phase === "initial" ? "generation" : `generation_${phase}`;
    console.log(`[${phase}] invoking the agent …`);
    const g = (meta[key] = generate(agent, level, a, expdir, project, phase));
    const tok = (g.tokens = recordTokens(usageKey, phase, path.join(expdir, g.log), a.usage_dir));
    console.log(`  rc=${g.rc} in ${g.seconds} s (log: ${path.join(expdir, g.log)})`);
    if (tok) console.log(`  tokens: ${tu.fmt(tok.total_tokens)} (input ${tu.fmt(tok.input_tokens)}, output ${tu.fmt(tok.output_tokens)})`);
    else console.log(`  WARNING: the agent's output carries no token usage; record it by hand: node js/token_usage.mjs record ${usageKey} --phase ${phase} …`);
    if (afterPhase) await afterPhase(phase);
  }
}

async function runGate(project, expdir, runId, domain, state) {
  console.log(`[acceptance] ${state}: starting PostgreSQL (docker compose), the backend and running the ${domain} cases …`);
  const acc = await acceptance(project, expdir, runId, 90, domain);
  if (acc.skipped) console.log(`   SKIPPED: ${acc.reason}. The functional gate was not run for ${runId}.`);
  else if (acc.error) console.log("   ERROR:", acc.error);
  else {
    console.log(`   ${acc.passed}/${acc.total} cases`);
    acc.state = state;
    fs.writeFileSync(path.join(expdir, ACCEPTANCE_FILE), dumps(acc, 1), "utf8");
  }
  return acc;
}

async function gateAfterPhases(phases, project, expdir, runId, a, meta) {
  if (phases.includes("initial")) return;
  if (!rt.hasR2(project)) meta.acceptance = await runGate(project, expdir, runId, a.domain, "project as found");
  else if (meta.acceptance && !meta.acceptance.skipped) console.log("[acceptance] the project implements r2: keeping the result of the gate run after phase initial.");
  else { meta.acceptance = { skipped: true, reason: rt.R2_GATE_SKIP }; console.log(`[acceptance] SKIPPED: ${rt.R2_GATE_SKIP}.`); }
}

function evaluateRun(project, res, runId, agent, level, a) {
  console.log("[evaluation] measuring maintainability …");
  const cmd = [NODE, path.join(JS, "evaluate.mjs"), "run", project, "--out", res, "--agent", agent, "--model", a.model || "n/a", "--level", level, "--domain", a.domain, "--run-id", runId];
  if (modelMissing(a.model)) cmd.push("--allow-missing-model");
  if (!a.skip_tests) cmd.push("--run-tests");
  if (!a.skip_tests && a.mutation) cmd.push("--mutation");
  if (a.accept_heuristics) cmd.push("--accept-heuristics");
  if (a.offline) cmd.push("--offline");
  if (a.as_of) cmd.push("--as-of", a.as_of);
  sh(cmd);
  if (a.dv8) {  // DL/PC with DV8, then a re-score (no new collection) to bring them into the profile
    console.log("[dv8] computing DL and PC …");
    if (sh([NODE, path.join(JS, "dv8_metrics.mjs"), res]) === 0) sh([NODE, path.join(JS, "evaluate.mjs"), "rescore", res]);
  }
}

function recordGeneratorModel(resultsDir, model) {
  const f = path.join(resultsDir, "environment.json");
  const env = fs.existsSync(f) ? loadJson(fs.readFileSync(f, "utf8")) : {};
  env.generator_model = modelMissing(model) ? null : str(model);
  env.generator_model_missing = modelMissing(model);
  fs.mkdirSync(resultsDir, { recursive: true });
  fs.writeFileSync(f, dumps(env, 1), "utf8");
}

export function parseArgs(argv) {
  const a = { agent: "claude", level: "N1,N2,N3", domain: "ecommerce", phase: null, usage_dir: tu.DEFAULT_DIR, repetitions: 1, model: null, agent_cmd: null,
    agent_timeout: 3600, existing_app: null, as_of: null, exp: "experiments", results: "results" };
  const bool = new Set(["allow_missing_model", "skip_acceptance", "skip_tests", "dv8", "accept_heuristics", "offline", "mutation"]);
  for (let i = 0; i < argv.length; i++) {
    const k = argv[i].replace(/^--/, "").replaceAll("-", "_");
    if (bool.has(k)) a[k] = true;
    else a[k] = ["repetitions", "agent_timeout"].includes(k) ? Number.parseInt(argv[++i], 10) : argv[++i];
  }
  return a;
}

export async function main(argv) {
  const a = parseArgs(argv);
  a.phase = a.phase || (a.existing_app ? "none" : "initial");
  let phases = a.phase === "none" ? [] : a.phase.split(",").map((p) => p.trim().toLowerCase());
  if (phases.some((p) => !PHASES.includes(p))) throw new Error(`ERROR: --phase accepts ${PHASES.join(", ")} (comma-separated) or none`);
  phases = PHASES.filter((p) => phases.includes(p));
  if (a.existing_app && phases.includes("initial")) throw new Error("ERROR: an --existing-app is already created: use --phase r2 or --phase none");
  if (!fs.existsSync(path.join(SPECS, `requirements-${a.domain}.md`))) throw new Error(`ERROR: specs/requirements-${a.domain}.md does not exist`);
  if (modelMissing(a.model) && !a.allow_missing_model) throw new Error("ERROR: " + MODEL_ERROR);
  const expRoot = path.resolve(a.exp), resRoot = path.resolve(a.results);
  recordGeneratorModel(resRoot, a.model);
  if (!a.skip_acceptance) {
    const [cmd, why] = rt.dockerStatus();
    if (cmd === null) console.log(`WARNING: ${why}. The acceptance gate will be SKIPPED for every run: the results will not say whether the apps work.`);
  }
  for (const agent of a.agent.split(","))
    for (const level of a.level.split(","))
      for (let rep = 1; rep <= a.repetitions; rep++) {
        const runId = `${agent}-${level.toLowerCase()}-${a.domain}-r${rep}`;
        const expdir = path.join(expRoot, runId);
        fs.mkdirSync(expdir, { recursive: true });
        const project = a.existing_app ? path.resolve(a.existing_app) : path.join(expdir, "project");
        const usageKey = a.existing_app ? path.basename(project) : runId;  // same key as `token_usage record <app>` and cli
        console.log(`\n=== ${runId} ===`);
        const meta = { run_id: runId, agent, level, domain: a.domain, repetition: rep, model: a.model, date: nowIso() };
        const afterPhase = async (phase) => {  // the gate runs on the state right after phase initial, before r2
          if (phase === "initial" && !a.skip_acceptance) meta.acceptance = await runGate(project, expdir, runId, a.domain, "after phase initial");
        };
        await runPhases(phases, agent, level, a, expdir, project, meta, usageKey, afterPhase);
        if (!a.skip_acceptance) await gateAfterPhases(phases, project, expdir, runId, a, meta);
        fs.writeFileSync(path.join(expdir, "meta.json"), dumps(meta, 1), "utf8");
        const res = path.join(resRoot, runId);
        evaluateRun(project, res, runId, agent, level, a);
        for (const f of [ACCEPTANCE_FILE, CONFORMANCE_FILE]) if (fs.existsSync(path.join(expdir, f))) fs.copyFileSync(path.join(expdir, f), path.join(res, f));
        if (fs.existsSync(tu.usagePath(usageKey, a.usage_dir))) fs.copyFileSync(tu.usagePath(usageKey, a.usage_dir), path.join(res, tu.RESULT_FILE));
      }
  console.log("\n=== comparison ===");
  sh([NODE, path.join(JS, "evaluate.mjs"), "aggregate", resRoot]);
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  main(process.argv.slice(2)).catch((e) => { console.error(e.message); process.exit(1); });
}

